    public static Result project(int army,Inputs inputs,List<Integer> oldPending,ArmyStrengthsAssaultCurrent.Release release){List<Reference> references=inputs==null?List.of():inputs.references();List<Integer> pending=inputs!=null&&inputs.pending()!=null?inputs.pending():oldPending;List<PendingOccurrence> current=ArmyStrengthsAssaultCurrent.observed(pending,false),derived=release!=null&&release.postPrefixReady()?release.queue().occurrences():null;boolean complete=release!=null&&release.postComplete();Selection a=select(current,current!=null,references,"captured_current_pending"),b=select(derived,complete,references,"conditional_release_pending_prefix_using_captured_current_context");Cleanup direct=cleanup(a,inputs,false),transferred=cleanup(b,inputs,true);return new Result(army,direct.ready()&&transferred.ready()?ArmyStrengths.Status.AVAILABLE:a.ready()||b.ready()?ArmyStrengths.Status.PARTIAL:ArmyStrengths.Status.UNAVAILABLE,a,b,direct,transferred);}
