    static ObjectNode emitTarget(CleanupTarget t){ObjectNode n=emitState(t.state()).put("native_index",t.index()).put("argument_full_id_u32",t.argument());n.set("helper_resolution",encodeResolution(t.resolution()));put(n,"selected_bucket_index_u32",t.bucketIndex());put(n,"bucket_count_raw_i32",t.count());put(n,"bucket_data_present",t.dataPresent());n.set("bucket_rows",buckets(t.rows()));return n;}
