    static ObjectNode emitSelection(Selection s){ObjectNode n=empty().put("scope",s.scope()).put("input_prefix_ready",s.prefixReady()).put("sequence_complete",s.complete()).put("selection_ready",s.ready()).put("first_removal_call_request_ready",s.call()!=null).put("selection_branch",s.branch()).put("remaining_unknown_tail",!s.complete()).put("post_first_removal_state_required",s.postRequired());ArrayNode invalid=n.putArray("known_invalid_prefix");for(Invalid i:s.invalid()){ObjectNode row=invalid.addObject().put("sequence_index",i.index());row.set("occurrence",ArmyStrengthsAssaultCurrent.encodeOccurrence(i.occurrence()));row.set("reference",emitReference(i.reference()));}n.set("first_removal_call_request",emitCall(s.call()));n.set("remaining_known_occurrences",ArmyStrengthsAssaultCurrent.occurrences(s.remaining()));n.set("missing_inputs",emitMissing(s.missing()));return n;}
